#include <list>
#include <iostream>

namespace stq {
template <typename T> void println(auto, const T &xz) {
    std::cout << '[';
    bool first{true};
    for (auto const &x : xz)
        std::cout << (first ? first = false, "" : ", ") << x;
    std::cout << "]\n";
}
} // namespace stq

int main() {
    std::list<int> numbers{1, 2, 3};
    stq::println("{}", numbers);
    while (not numbers.empty()) {
        numbers.pop_back();
        stq::println("{}", numbers);
    }
}
